package ru.truetv.launcher;
import android.app.*;
import android.content.*;
import android.os.*;
import android.preference.Preference;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
/** Actual Activity windows for the 2.1.5 add-flow rollback, on a disposable VM only. */
public final class PinFlowCheck extends Instrumentation {
 private HomeActivity home;private CatalogActivity picker;private SettingsActivity settings;private int checks;private Context c;private final StringBuilder log=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean v,String msg){log.append(v?"PASS ":"FAIL ").append(msg).append('\n');checks++;if(!v)throw new AssertionError(msg);}
 private void main(Runnable r){Throwable[] e={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){e[0]=t;}});waitForIdleSync();if(e[0]!=null)throw new AssertionError(e[0]);}
 private String shell(String s)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(s);InputStream in=new FileInputStream(fd.getFileDescriptor());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),"UTF-8").trim();}}
 private CatalogActivity open(int slot)throws Exception{ActivityMonitor m=new ActivityMonitor(CatalogActivity.class.getName(),null,false);addMonitor(m);main(()->home.board.getChildAt(slot).performClick());CatalogActivity result=(CatalogActivity)waitForMonitorWithTimeout(m,12000);removeMonitor(m);check(result!=null,"plus starts standalone catalog Activity");VmWindows.ready(this);return result;}
 private int index(String pkg){for(int i=0;i<picker.grid.getAdapter().getCount();i++)if(((AppCatalog.Entry)picker.grid.getAdapter().getItem(i)).pkg.equals(pkg))return i;throw new AssertionError(pkg);}
 private void pick(String pkg)throws Exception{int at=index(pkg);main(()->picker.grid.performItemClick(picker.grid.getAdapter().getView(at,null,picker.grid),at,at));long end=SystemClock.uptimeMillis()+12000;while((!picker.isFinishing()||!home.hasWindowFocus())&&SystemClock.uptimeMillis()<end){waitForIdleSync();Thread.sleep(80);}check(picker.isFinishing()&&home.hasWindowFocus(),"catalog finishes and existing Home owns focus");picker=null;}
 private void shot(String name)throws Exception{VmWindows.ready(this);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(c.getExternalFilesDir(null),name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 private void clickPreference(Preference p)throws Exception{Method m=Preference.class.getDeclaredMethod("performClick",android.preference.PreferenceScreen.class);m.setAccessible(true);main(()->{try{m.invoke(p,settings.getPreferenceScreen());}catch(Exception e){throw new AssertionError(e);}});}
 private void slowStatusCheck()throws Exception{
  final java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);final java.util.concurrent.atomic.AtomicInteger uiCalls=new java.util.concurrent.atomic.AtomicInteger(),callbacks=new java.util.concurrent.atomic.AtomicInteger();
  Context fake=new ContextWrapper(c){public Context getApplicationContext(){return this;}public Object getSystemService(String name){if(Looper.myLooper()==Looper.getMainLooper()){uiCalls.incrementAndGet();return null;}if(Context.BLUETOOTH_SERVICE.equals(name)){entered.countDown();try{release.await(6,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}return null;}return super.getSystemService(name);}};
  StatusWatch watch=new StatusWatch(fake,new StatusWatch.Listener(){public java.util.List<String> visiblePackages(){return java.util.Collections.emptyList();}public void status(boolean v,String o,int b,java.util.Set<String> l){callbacks.incrementAndGet();}});
  try{main(watch::start);check(entered.await(5,java.util.concurrent.TimeUnit.SECONDS),"slow vendor status request reached worker");main(watch::stop);check(uiCalls.get()==0,"start/stop issue no platform service calls on UI thread");main(()->{});check(callbacks.get()==0,"blocked status request cannot delay UI or update paused view");}finally{release.countDown();main(watch::stop);}
 }
 public void onStart(){Bundle done=new Bundle();c=getTargetContext();try{
  check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"disposable VM guard");VmWindows.prepare(this);new SettingsStore(c).data.edit().clear().putBoolean("bt_asked",true).commit();slowStatusCheck();home=VmWindows.home(this);long end=SystemClock.uptimeMillis()+20000;while(!AppCatalog.get(c).loaded()&&SystemClock.uptimeMillis()<end)Thread.sleep(60);
  shell(Build.VERSION.SDK_INT>=29?"cmd role add-role-holder --user 0 android.app.role.HOME ru.truetv.launcher 1":"cmd package set-home-activity ru.truetv.launcher/.HomeActivity");check(HomeDefaults.isOwn(shell(HomeDefaults.query(0))),"test Home default confirmed");
  for(int n=0;n<3;n++){
   ActivityMonitor m=new ActivityMonitor(SettingsActivity.class.getName(),null,false);addMonitor(m);main(()->home.header.getChildAt(3).performClick());settings=(SettingsActivity)waitForMonitorWithTimeout(m,12000);removeMonitor(m);check(settings!=null,"settings opens with content, cycle "+n);VmWindows.ready(this);check(settings.getListView().getChildCount()>0,"settings has drawn preference rows, cycle "+n);
   if(n==0){check(settings.findPreference("access_service").getTitle().toString().equals(Ui.word(c,"Служебное управление приложениями (перезапуск и выключение)","App service control (restart and stop)")),"requested service title is exact");clickPreference(settings.findPreference("home"));Field f=ActionSheet.class.getDeclaredField("active");f.setAccessible(true);Object active=((java.lang.ref.WeakReference<?>)f.get(null)).get();Field dialog=ActionSheet.class.getDeclaredField("dialog");dialog.setAccessible(true);check(active!=null&&((Dialog)dialog.get(active)).isShowing(),"Default Home preference opens own menu");shot("settings219-menu.png");Dialog ownDialog=(Dialog)dialog.get(active);main(ownDialog::dismiss);}
   shell("input keyevent 3");end=SystemClock.uptimeMillis()+12000;while(!home.hasWindowFocus()&&SystemClock.uptimeMillis()<end){VmWindows.clear(this);waitForIdleSync();Thread.sleep(80);}check(home.hasWindowFocus()&&!home.isDestroyed(),"Home key returns from settings to same Home, cycle "+n);
   picker=open(n);Board old=home.board;check(picker.grid.getAdapter().getCount()>0,"catalog has app content");pick("ru.truetv.probe");check(home.board==old,"catalog return updates existing tile without rebuilding desktop");check(((Tile)home.board.getChildAt(n)).pkg.equals("ru.truetv.probe")&&new SettingsStore(c).slot(n).equals("ru.truetv.probe"),"exact slot saved and tile visible, cycle "+n);
  }
  picker=open(4);main(picker::onBackPressed);end=SystemClock.uptimeMillis()+10000;while(!home.hasWindowFocus()&&SystemClock.uptimeMillis()<end){waitForIdleSync();Thread.sleep(60);}check(new SettingsStore(c).slot(4).isEmpty()&&home.hasWindowFocus(),"Back cancels without a saved assignment");picker=null;
  picker=open(4);ActivityMonitor recreated=new ActivityMonitor(CatalogActivity.class.getName(),null,false);addMonitor(recreated);main(picker::recreate);picker=(CatalogActivity)waitForMonitorWithTimeout(recreated,12000);removeMonitor(recreated);check(picker!=null&&picker.getIntent().getIntExtra("slot",-1)==4,"catalog recreation retains target slot");VmWindows.ready(this);pick("ru.truetv.launcher.tests");check(((Tile)home.board.getChildAt(4)).pkg.equals("ru.truetv.launcher.tests"),"no-launch-Activity app can still be assigned");
  Board before=home.board;shell("input keyevent 3 3");waitForIdleSync();check(home.board==before&&!home.isDestroyed(),"double Home while already Home keeps existing board");check(HomeDefaults.isOwn(shell(HomeDefaults.query(0))),"double Home does not change default");shot("home219-rollback.png");
  String state=shell("dumpsys activity activities");int records=0;for(String line:state.split("\n"))if(line.contains("* Hist #")&&line.contains("ru.truetv.launcher/.HomeActivity"))records++;check(records==1,"task history has exactly one Home Activity");
  done.putBoolean("passed",true);done.putString("report",log+"Checks="+checks);
 }catch(Throwable t){StringWriter trace=new StringWriter();t.printStackTrace(new PrintWriter(trace));done.putBoolean("passed",false);done.putString("report",log+trace.toString());}finally{try{if(picker!=null)main(picker::finish);if(settings!=null)main(settings::finish);shell(Build.VERSION.SDK_INT>=29?"cmd role add-role-holder --user 0 android.app.role.HOME com.android.launcher3 1":"cmd package set-home-activity com.android.launcher3/.Launcher");}catch(Exception ignored){}}finish(done.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,done);}
}
